Here are the changes to implement the "Edit Comment" feature:

### 1. Add `comment:update` Policy
Modified `src/lib/authorization.tsx` to include an authorization policy for updating comments.

**apps/react-vite/src/lib/authorization.tsx**
```tsx
export const POLICIES = {
  'comment:delete': (user: User, comment: Comment) => {
    if (user.role === 'ADMIN') {
      return true;
    }

    if (user.role === 'USER' && comment.author?.id === user.id) {
      return true;
    }

    return false;
  },
  'comment:update': (user: User, comment: Comment) => {
    if (user?.role === 'ADMIN') {
      return true;
    }

    if (user?.role === 'USER' && comment.author?.id === user?.id) {
      return true;
    }

    return false;
  },
};
```

### 2. Create Update Comment API Hook
Created `src/features/comments/api/update-comment.ts` with the PATCH request logic and React Query hook.

**apps/react-vite/src/features/comments/api/update-comment.ts**
```tsx
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';
import { Comment } from '@/types/api';
import { useNotifications } from '@/components/ui/notifications'; // Success notification handled in the hook

import { getInfiniteCommentsQueryOptions } from './get-comments';

export const updateCommentInputSchema = z.object({
  body: z.string().min(1, 'Required'),
});

export type UpdateCommentInput = z.infer<typeof updateCommentInputSchema>;

export const updateComment = ({
  commentId,
  data,
}: {
  commentId: string;
  data: UpdateCommentInput;
}): Promise<Comment> => {
  return api.patch(`/comments/${commentId}`, data);
};

type UseUpdateCommentOptions = {
  discussionId: string;
  mutationConfig?: MutationConfig<typeof updateComment>;
};

export const useUpdateComment = ({
  mutationConfig,
  discussionId,
}: UseUpdateCommentOptions) => {
  const queryClient = useQueryClient();
  const { addNotification } = useNotifications();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      queryClient.invalidateQueries({
        queryKey: getInfiniteCommentsQueryOptions(discussionId).queryKey,
      });
      addNotification({
        type: 'success',
        title: 'Comment Updated',
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updateComment,
  });
};
```

### 3. Add PATCH Handler to Mock Server
Updated `src/testing/mocks/handlers/comments.ts` to support the new `PATCH` route, ensuring only the author (or admin) can update the comment.

**apps/react-vite/src/testing/mocks/handlers/comments.ts**
```tsx
// ... inside the existing commentsHandlers array, add this before the closing bracket:

  http.patch(`${env.API_URL}/comments/:commentId`, async ({ params, request, cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const commentId = params.commentId as string;
      const data = (await request.json()) as { body: string };

      const comment = db.comment.findFirst({
        where: { id: { equals: commentId } },
      });

      if (!comment) {
        return HttpResponse.json({ message: 'Comment not found' }, { status: 404 });
      }

      if (comment.authorId !== user?.id) {
        return HttpResponse.json({ message: 'Not authorized' }, { status: 403 });
      }

      const result = db.comment.update({
        where: { id: { equals: commentId } },
        data: { body: data.body },
      });

      await persistDb('comment');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),
];
```

### 4. Add Edit Button and Form Drawer to Comment List
Modified `src/features/comments/components/comments-list.tsx` to show the Edit button (only for the author) and manage the form drawer state.

**apps/react-vite/src/features/comments/components/comments-list.tsx**
```tsx
import { useEffect, useState } from 'react';
import { ArchiveX, Pencil } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Form, Textarea } from '@/components/ui/form';
import { MDPreview } from '@/components/ui/md-preview';
import { Spinner } from '@/components/ui/spinner';
import { useUser } from '@/lib/auth';
import { POLICIES, Authorization } from '@/lib/authorization';
import { User } from '@/types/api';
import { formatDate } from '@/utils/format';
import { 
  Drawer, 
  DrawerClose, 
  DrawerContent, 
  DrawerFooter, 
  DrawerHeader, 
  DrawerTitle 
} from '@/components/ui/drawer';
import { useDisclosure } from '@/hooks/use-disclosure';

import { useInfiniteComments } from '../api/get-comments';
import { useUpdateComment, updateCommentInputSchema } from '../api/update-comment';
import { DeleteComment } from './delete-comment';

type CommentsListProps = {
  discussionId: string;
};

export const CommentsList = ({ discussionId }: CommentsListProps) => {
  const user = useUser();
  const commentsQuery = useInfiniteComments({ discussionId });
  const [editingComment, setEditingComment] = useState<{ id: string; body: string } | null>(null);
  const { open, close, isOpen } = useDisclosure();

  const updateCommentMutation = useUpdateComment({
    discussionId,
    mutationConfig: {
      onSuccess: () => {
        setEditingComment(null);
      },
    },
  });

  // Automatically open the drawer when an editing comment is selected
  useEffect(() => {
    if (editingComment) open();
  }, [editingComment, open]);

  if (commentsQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const comments = commentsQuery.data?.pages.flatMap((page) => page.data);

  if (!comments?.length)
    return (
      <div
        role="list"
        aria-label="comments"
        className="flex h-40 flex-col items-center justify-center bg-white text-gray-500"
      >
        <ArchiveX className="size-10" />
        <h4>No Comments Found</h4>
      </div>
    );

  return (
    <>
      {/* Edit Form Drawer */}
      {editingComment && (
        <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/50">
          <Drawer 
            open={isOpen} 
            onOpenChange={(isOpen) => !isOpen && close()} 
            side="bottom" 
            className="w-full max-w-2xl"
          >
            <DrawerContent className="top-20 flex max-w-[800px] flex-col sm:max-w-[540px]">
              <div className="flex flex-col gap-4 p-6">
                <DrawerHeader className="px-0">
                  <DrawerTitle className="text-xl font-bold">Edit Comment</DrawerTitle>
                </DrawerHeader>

                <Form
                  id="edit-comment"
                  onSubmit={(values) => {
                    if (editingComment) {
                      updateCommentMutation.mutate({ 
                        commentId: editingComment.id, 
                        data: values 
                      });
                    }
                  }}
                  schema={updateCommentInputSchema}
                  options={{
                    defaultValues: {
                      body: editingComment.body,
                    },
                  }}
                >
                  {({ register, formState }) => (
                    <Textarea
                      label="Body"
                      error={formState.errors['body']}
                      registration={register('body')}
                    />
                  )}
                </Form>
              </div>
              <DrawerFooter className="gap-3 pt-0 sm:gap-0">
                <DrawerClose asChild>
                  <Button variant="outline">Close</Button>
                </DrawerClose>
                <Button
                  isLoading={updateCommentMutation.isPending}
                  disabled={updateCommentMutation.isPending}
                  onClick={(e) => {
                    const form = document.getElementById('edit-comment');
                    form?.dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
                  }}
                >
                  Update
                </Button>
              </DrawerFooter>
            </DrawerContent>
          </Drawer>
        </div>
      )}

      <ul aria-label="comments" className="flex flex-col space-y-3">
        {comments.map((comment, index) => (
          <li
            aria-label={`comment-${comment.body}-${index}`}
            key={comment.id || index}
            className="w-full bg-white p-4 shadow-sm"
          >
            <Authorization
              policyCheck={POLICIES['comment:delete'](
                user.data as User,
                comment,
              )}
            >
              <div className="flex justify-between">
                <div>
                  <span className="text-xs font-semibold">
                    {formatDate(comment.createdAt)}
                  </span>
                  {comment.author && (
                    <span className="text-xs font-bold">
                      {' '}
                      by {comment.author.firstName} {comment.author.lastName}
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-2">
                  {/* Edit Button - Visible only to the author */}
                  {user.data?.id === comment.author?.id && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setEditingComment({ id: comment.id, body: comment.body })}
                      icon={<Pencil className="size-4" />}
                    >
                      Edit
                    </Button>
                  )}
                  <DeleteComment discussionId={discussionId} id={comment.id} />
                </div>
              </div>
            </Authorization>

            <MDPreview value={comment.body} />
          </li>
        ))}
      </ul>
      {commentsQuery.hasNextPage && (
        <div className="flex items-center justify-center py-4">
          <Button onClick={() => commentsQuery.fetchNextPage()}>
            {commentsQuery.isFetchingNextPage ? (
              <Spinner />
            ) : (
              'Load More Comments'
            )}
          </Button>
        </div>
      )}
    </>
  );
};
```

